 private const LEASES='var/imperium/offices/clavium/governance-cognition-leases',CLAIMS='var/imperium/runtime/governance-cognition-invocation-claims',OCCUPANCY='var/imperium/operational/occupancy',DISPOSITIONS='var/imperium/runtime/continuous-governance-revocation-dispositions';private RecordReferenceValidator $validator;private ImmutableRecordStore $records;private AtomicTransition $atomic;
 public function __construct(#[Autowire('%kernel.project_dir%')]private string$root,?RecordReferenceValidator$v=null,?ImmutableRecordStore$r=null,?AtomicTransition$a=null){$this->validator=$v??new RecordReferenceValidator($root);$this->atomic=$a??new AtomicTransition($root);$this->records=$r??new ImmutableRecordStore($root,$this->atomic);}
 public function interrupt(string$leaseId,string$seneschalBindingId,string$reason,\DateTimeImmutable$effectiveAt):array
 {
  $reason=trim($reason);if(!preg_match('/^governance-cognition-lease-[a-f0-9]{20}$/',$leaseId)||!preg_match('/^operational-seat-binding-[a-f0-9]{20}$/',$seneschalBindingId)||''===$reason)throw new \InvalidArgumentException('CAG1200_LEASE_INTERRUPTION_INPUT_INVALID');
