 private function assertUnclaimedLease(string$id,array$l,\DateTimeImmutable$at):void
 {if(!$this->validator->isIntact($l)||'imperium.clavium-governance-cognition-lease/v1'!==($l['schema']??null)||$id!==($l['lease_id']??null)||'GOVERNANCE_COGNITION_LEASE_ISSUED_PENDING_DURABLE_INVOCATION_CLAIM'!==($l['status']??null)||true!==($l['opaque']??null)||true!==($l['lease_single_use']??null)||false!==($l['lease_consumed']??null)||new \DateTimeImmutable((string)($l['issued_at']??'2999-01-01'))>$at||new \DateTimeImmutable((string)($l['expires_at']??'1970-01-01'))<=$at||true!==($l['sealed']??null))throw new \RuntimeException('CAG1203_GOVERNANCE_LEASE_NOT_INTERRUPTIBLE_UNCLAIMED');foreach(glob($this->root.'/'.self::CLAIMS.'/*.json')?:[]as$p){$c=$this->validator->read($p,'CAG1204_GOVERNANCE_CLAIM_UNREADABLE');if(($c['lease_consumption']['lease_id']??null)===$id)throw new \RuntimeException('CAG1203_GOVERNANCE_LEASE_NOT_INTERRUPTIBLE_UNCLAIMED');}}
 private function currentSeneschal(string$id,array$o,string$instance):array
 {if(!$this->validator->isIntact($o)||$id!==($o['binding_id']??null)||$instance!==($o['instance_id']??null)||'curia.seneschal'!==($o['seat']??null)||'ACTIVE'!==($o['status']??null)||true!==($o['sealed']??null)||!is_string($o['manifestation_id']??null)||!is_int($o['occupancy_generation']??null))throw new \RuntimeException('CAG1205_SENESCHAL_NOT_COMPETENT_CURRENT_OCCUPANT');foreach(glob($this->root.'/'.self::OCCUPANCY.'/*.json')?:[]as$p){$x=$this->validator->read($p,'CAG1205_SENESCHAL_NOT_COMPETENT_CURRENT_OCCUPANT');if('curia.seneschal'===($x['seat']??null)&&'ACTIVE'===($x['status']??null)&&$instance===($x['instance_id']??null)&&$id!==($x['binding_id']??null))throw new \RuntimeException('CAG1205_SENESCHAL_NOT_COMPETENT_CURRENT_OCCUPANT');}return['seat'=>'curia.seneschal','binding_id'=>$id,'binding_digest'=>$o['record_digest'],'manifestation_id'=>$o['manifestation_id'],'occupancy_generation'=>$o['occupancy_generation']];}
}
